<?php declare(strict_types=1); use App\Application\Review\AI\NotebookAnalysisResponseValidator;use App\Application\Review\Service\ApplyNotebookAnalysisActionsService;use App\Application\Review\Service\ApplyNotebookAnalysisSignalsService;use App\Application\Review\Service\BuildNotebookPerformanceSummaryService;use App\Application\Review\Service\CreateOrReuseFlashcardService;use App\Application\Review\Service\ProcessNextNotebookAnalysisService;use App\Application\Review\Service\ProcessNotebookAnalysisService;use App\Infrastructure\Persistence\Doctrine\DoctrineEntityManagerFactory;use App\Infrastructure\Persistence\Doctrine\DoctrineTransactionManager;use App\Infrastructure\Persistence\Doctrine\Review\DoctrineFlashcardRepository;use App\Infrastructure\Persistence\Doctrine\Review\DoctrineNotebookAnalysisActionRepository;use App\Infrastructure\Persistence\Doctrine\Review\DoctrineNotebookAnalysisExecutionRepository;use App\Infrastructure\Persistence\Doctrine\Review\DoctrineUserConceptMasteryRepository;use App\Infrastructure\Persistence\Doctrine\Review\DoctrineUserFlashcardProgressRepository;use App\Infrastructure\Persistence\Doctrine\Study\DoctrineNotebookProgressReader;use App\Infrastructure\Persistence\Doctrine\Taxonomy\DoctrineTaxonomySubjectRepository;require __DIR__.'/../vendor/autoload.php';$command=trim((string)getenv('NOTEBOOK_ANALYSIS_PROVIDER_COMMAND'));if($command===''){fwrite(STDERR,"NOTEBOOK_ANALYSIS_PROVIDER_COMMAND não configurado\n");exit(2);}$em=DoctrineEntityManagerFactory::create();$executions=new DoctrineNotebookAnalysisExecutionRepository($em);$transactions=new DoctrineTransactionManager($em);$cards=new DoctrineFlashcardRepository($em);$mastery=new DoctrineUserConceptMasteryRepository($em);$progress=new DoctrineUserFlashcardProgressRepository($em);$actions=new DoctrineNotebookAnalysisActionRepository($em);$processor=new ProcessNotebookAnalysisService($executions,new BuildNotebookPerformanceSummaryService(new DoctrineNotebookProgressReader($em)),new NotebookAnalysisResponseValidator());$consumer=new ProcessNextNotebookAnalysisService($executions,$processor);$applier=new ApplyNotebookAnalysisActionsService(new CreateOrReuseFlashcardService($cards,new DoctrineTaxonomySubjectRepository($em)),new ApplyNotebookAnalysisSignalsService($mastery,$progress),$actions,$transactions);$provider=static function(array $payload)use($command):array{$process=proc_open($command,[0=>['pipe','r'],1=>['pipe','w'],2=>['pipe','w']],$pipes);if(!is_resource($process))throw new RuntimeException('Provider de análise indisponível.');fwrite($pipes[0],json_encode($payload,JSON_THROW_ON_ERROR));fclose($pipes[0]);$output=stream_get_contents($pipes[1]);$error=stream_get_contents($pipes[2]);fclose($pipes[1]);fclose($pipes[2]);if(proc_close($process)!==0)throw new RuntimeException('Provider de análise falhou: '.mb_substr((string)$error,0,160));$decoded=json_decode((string)$output,true,512,JSON_THROW_ON_ERROR);if(!is_array($decoded))throw new RuntimeException('Provider não retornou objeto JSON.');return $decoded;};$processed=0;while($consumer->execute($provider,static fn(string $executionId,string $userId,array $items,DateTimeImmutable $now)=>$applier->execute($executionId,$userId,$items,$now),new DateTimeImmutable('now',new DateTimeZone('UTC')))){$em->flush();$em->clear();$processed++;}fwrite(STDOUT,"Processed {$processed} notebook analysis job(s)\n");
